import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../l10n/l10n.dart';
import '../../providers/providers.dart';
import '../../themes/stack_colors.dart';
import '../../utilities/text_styles.dart';
import '../../utilities/util.dart';
import '../custom_buttons/blue_text_button.dart';
import 'sub_widgets/wallet_info_row_balance.dart';
import 'sub_widgets/wallet_info_row_coin_icon.dart';

class WalletInfoRow extends ConsumerWidget {
  const WalletInfoRow({
    super.key,
    required this.walletId,
    this.onPressedDesktop,
    this.padding = const EdgeInsets.all(0),
  });

  final String walletId;
  final VoidCallback? onPressedDesktop;
  final EdgeInsets padding;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final wallet = ref.watch(pWallets).getWallet(walletId);
    if (Util.isDesktop) {
      return Padding(
        padding: padding,
        child: Container(
          color: Colors.transparent,
          child: Row(
            children: [
              Expanded(
                flex: 3,
                child: Row(
                  children: [
                    WalletInfoCoinIcon(coin: wallet.info.coin),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Text(
                        wallet.info.name,
                        overflow: TextOverflow.ellipsis,
                        style: STextStyles.desktopTextExtraSmall(context)
                            .copyWith(
                              color: Theme.of(context)
                                  .extension<StackColors>()!
                                  .textDark,
                            ),
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                flex: 4,
                child: WalletInfoRowBalance(walletId: walletId),
              ),
              Expanded(
                flex: 2,
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.end,
                  children: [
                    CustomTextButton(
                      text: l10n.walletOpen,
                      onTap: onPressedDesktop,
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      );
    } else {
      return Row(
        children: [
          WalletInfoCoinIcon(coin: wallet.info.coin),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(wallet.info.name, style: STextStyles.titleBold12(context)),
                const SizedBox(height: 2),
                WalletInfoRowBalance(walletId: walletId),
              ],
            ),
          ),
        ],
      );
    }
  }
}
